import os
from typing import Any, Dict, List, Optional

from mindee import Client, APIError, ServerError
from mindee.documents import InvoiceV4

REQUIRED_FIELDS = [
    "supplier_name",
    "invoice_number",
    "invoice_date",
    "total_amount",
    "currency",
]


class StructuredDocumentExtractionError(Exception):
    pass


def _confidence_to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("value", "content", "raw_value"):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val
    return field


def _field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    for attr in ("confidence", "score", "probability"):
        if hasattr(field, attr):
            conf = _confidence_to_float(getattr(field, attr))
            if conf is not None:
                return conf
    return None


def _extract_from_invoice_doc(invoice_doc: Any) -> Dict[str, Any]:
    fields: Dict[str, Any] = {}

    candidates = {
        "supplier_name": [
            ("supplier_name",),
            ("supplier", "name"),
            ("seller_name",),
            ("vendor_name",),
        ],
        "invoice_number": [
            ("invoice_number",),
            ("invoice_no",),
            ("number",),
            ("reference_number",),
        ],
        "invoice_date": [
            ("invoice_date",),
            ("date",),
            ("issue_date",),
        ],
        "total_amount": [
            ("total_amount",),
            ("amount",),
            ("total",),
            ("total_with_tax",),
        ],
        "currency": [
            ("currency",),
        ],
    }

    def resolve_path(obj: Any, path: tuple) -> Any:
        cur = obj
        for part in path:
            if cur is None:
                return None
            if isinstance(cur, dict):
                cur = cur.get(part)
            else:
                cur = getattr(cur, part, None)
        return cur

    for key, paths in candidates.items():
        found = None
        for path in paths:
            found = resolve_path(invoice_doc, path)
            if found is not None:
                break

        value = _field_value(found)
        confidence = _field_confidence(found)

        fields[key] = {
            "value": value,
            "confidence": confidence,
        }

    return fields


def validate_structured_document(
    document_path: str,
    min_confidence: float = 0.80,
) -> Dict[str, Any]:
    if not os.path.exists(document_path):
        raise FileNotFoundError(f"Document not found: {document_path}")

    api_key = os.getenv("MINDEE_API_KEY")
    if not api_key:
        raise StructuredDocumentExtractionError("MINDEE_API_KEY is required")

    client = Client(api_key=api_key)

    try:
        with open(document_path, "rb") as file_handle:
            doc = client.parse(InvoiceV4, file_handle)

        invoice_doc = getattr(doc, "document", doc)
        extracted = _extract_from_invoice_doc(invoice_doc)

        missing_fields: List[str] = []
        low_confidence_fields: Dict[str, float] = {}

        for field_name, data in extracted.items():
            value = data.get("value")
            confidence = data.get("confidence")

            if value in (None, "", [], {}):
                missing_fields.append(field_name)

            if confidence is None:
                low_confidence_fields[field_name] = 0.0
            elif confidence < min_confidence:
                low_confidence_fields[field_name] = confidence

        is_valid = not missing_fields and not low_confidence_fields

        return {
            "valid": is_valid,
            "required_fields": extracted,
            "missing_fields": missing_fields,
            "low_confidence_fields": low_confidence_fields,
            "min_confidence": min_confidence,
        }

    except (APIError, ServerError) as exc:
        raise StructuredDocumentExtractionError(str(exc)) from exc
    except Exception as exc:
        raise StructuredDocumentExtractionError(str(exc)) from exc
